tool.command:

  ln -f -s ${input_graph_path} ${input_graph_path}_`echo $$`.${input_graph_path.ext};

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

communities

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____dq__algorithm__dq__:__dq__${properties.algorithm}__dq__,__dq__resolution__dq__:${properties.resolution},__dq__max_levels__dq__:${properties.max_levels},__dq__remove_tmp__dq__:${properties.remove_tmp},__dq__restart__dq__:${properties.restart}__cc____cc__'
  #end if

  #if str($input_graph_path) != 'None':
    --input_graph_path ${input_graph_path}_`echo $$`.${input_graph_path.ext}
  #end if


  --output_communities_path $outname_output_communities_path
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

  rm -f ${input_graph_path}_`echo $$`.${input_graph_path.ext};


  if test -f $outname_output_communities_path; then mv $outname_output_communities_path $output_communities_path; fi;
